function solve(beginWord, endWord, wordList) {
  if (beginWord === endWord) return [[beginWord]];
  if (wordList.indexOf(endWord) === -1) return [];
  function differs(a, b) {
    if (a.length !== b.length) return false;
    let c = 0;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) c++;
    return c === 1;
  }
  function compare(a, b) {
    for (let i = 0; i < a.length && i < b.length; i++) {
      if (a[i] < b[i]) return -1;
      if (a[i] > b[i]) return 1;
    }
    return a.length - b.length;
  }
  let frontier = [[beginWord]];
  let result = [];
  while (frontier.length > 0) {
    const next = [];
    for (const path of frontier) {
      const last = path[path.length - 1];
      for (const w of wordList) {
        if (path.indexOf(w) !== -1) continue;
        if (differs(last, w)) next.push(path.concat([w]));
      }
    }
    const found = next.filter((path) => path[path.length - 1] === endWord);
    if (found.length > 0) {
      result = found;
      break;
    }
    frontier = next;
  }
  result.sort(compare);
  return result;
}

function solve(beginWord, endWord, wordList) {
  if (beginWord === endWord) return [[beginWord]];
  const words = [];
  const seen = new Set();
  for (const w of wordList) {
    if (!seen.has(w)) { seen.add(w); words.push(w); }
  }
  if (!seen.has(endWord)) return [];
  function differs(a, b) {
    if (a.length !== b.length) return false;
    let c = 0;
    for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) c++;
    return c === 1;
  }
  function compare(a, b) {
    for (let i = 0; i < a.length && i < b.length; i++) {
      if (a[i] < b[i]) return -1;
      if (a[i] > b[i]) return 1;
    }
    return a.length - b.length;
  }
  const dist = new Map();
  dist.set(beginWord, 0);
  let frontier = [beginWord];
  while (frontier.length > 0) {
    const next = [];
    for (const w of frontier) {
      for (const x of words) {
        if (!dist.has(x) && differs(w, x)) {
          dist.set(x, dist.get(w) + 1);
          next.push(x);
        }
      }
    }
    frontier = next;
  }
  if (!dist.has(endWord)) return [];
  const res = [];
  function dfs(word, path) {
    if (word === endWord) {
      res.push(path.slice());
      return;
    }
    for (const x of words) {
      if (dist.has(x) && dist.get(x) === dist.get(word) + 1 && differs(word, x)) {
        path.push(x);
        dfs(x, path);
        path.pop();
      }
    }
  }
  dfs(beginWord, [beginWord]);
  res.sort(compare);
  return res;
}
